  const targetLevel = level.charAt(0).toUpperCase() + level.slice(1);
  const levelMap = {
    "beginner": "A1",
    "elementary": "A2",
    "intermediate": "B1",
    "upper-intermediate": "B2",
    "advanced": "C1",
    "mastery": "C2"
  };
  const cefr = levelMap[level.toLowerCase()] || "B1";
  const candidates = library.sentences.filter((s) => s.cefr_level === cefr);
